<template><NuxtLayout><div class="page-heading"><div><div class="eyebrow">ONE STEP AT A TIME</div><h1>My tasks<span class="heading-dot">.</span></h1><p class="muted">Keep your focus on what moves you forward.</p></div><button class="btn primary" @click="open">＋ New task</button></div><div class="toolbar"><div class="search-box"><span>⌕</span><input v-model="tasks.search" placeholder="Search tasks…"></div><select v-model="tasks.filter" class="filter-select"><option value="all">All statuses</option><option value="todo">To do</option><option value="in-progress">In progress</option><option value="done">Done</option></select></div><section class="panel all-tasks"><div v-if="!tasks.filtered.length" class="empty-state"><div class="empty-icon">☷</div><b>No matching tasks</b><p>Try another filter or create a new task.</p><button class="btn soft" @click="open">＋ Create task</button></div><div v-else class="task-list"><article v-for="t in tasks.filtered" :key="t._id" class="task-row"><button class="check-circle" :class="{checked:t.status==='done'}" @click="toggle(t)">{{t.status==='done'?'✓':''}}</button><div class="task-main"><b :class="{completed:t.status==='done'}">{{t.title}}</b><small><span class="project-dot" :class="t.project?.color"/>{{t.project?.name || 'Project'}} <span v-if="t.dueDate">· Due {{date(t.dueDate)}}</span></small><small v-if="t.description" class="task-description">{{t.description}}</small></div><span class="status-pill" :class="t.status">{{statusLabel(t.status)}}</span><span class="priority" :class="t.priority">{{t.priority}}</span><button class="more-btn" @click="edit(t)">···</button></article></div></section><TaskModal v-if="modal" :task="selected" :projects="projects.items" @close="modal=false" @save="save"/></NuxtLayout></template>
<script setup>
const tasks=useTasksStore(),projects=useProjectsStore();const modal=ref(false),selected=ref(null);onMounted(async()=>{await Promise.all([projects.fetchAll(),tasks.fetchAll()])});
function open(){selected.value=null;modal.value=true}function edit(t){selected.value=t;modal.value=true}
async function save(payload){if(selected.value)await tasks.update(selected.value._id,payload);else await tasks.create(payload);await Promise.all([projects.fetchAll(),tasks.fetchAll()]);modal.value=false;selected.value=null}
async function toggle(t){await tasks.update(t._id,{status:t.status==='done'?'todo':'done'});await tasks.fetchAll()}
function date(d){return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function statusLabel(s){return {'todo':'To do','in-progress':'In progress','done':'Done'}[s]}
</script>
